const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  const s = (v) => (v === null || v === undefined ? null : String(v).trim() || null);
  const booking_ref = s(j.booking_ref), to_stylist = s(j.to_stylist_id), from_stylist = s(j.from_stylist_id);
  out.push({ json: { booking_ref, to_stylist, from_stylist,
                     invalid: (booking_ref && to_stylist && from_stylist) ? null : 'invalid_input' } });
}
if (out.length === 0) out.push({ json: { booking_ref: null, to_stylist: null, from_stylist: null, invalid: 'invalid_input' } });
return out;

const checked = $('Validate input').all();
const out = [];
const rows = $input.all();
for (let i = 0; i < rows.length; i++) {
  const v = (checked[i] || checked[0] || {}).json || {};
  const row = (rows[i] || {}).json || {};
  if (v.invalid) { out.push({ json: { ok: false, reason: v.invalid } }); continue; }
  if (row.error !== undefined || !row.result) { out.push({ json: { ok: false, reason: 'db_unavailable' } }); continue; }
  const d = row.result;
  if (!d.found)          { out.push({ json: { ok: false, reason: 'booking_not_found' } }); continue; }
  if (d.status !== 'confirmed') { out.push({ json: { ok: false, reason: 'not_confirmed' } }); continue; }
  if (!d.in_future)      { out.push({ json: { ok: false, reason: 'already_started' } }); continue; }
  if (!d.still_theirs)   { out.push({ json: { ok: false, reason: 'already_reassigned' } }); continue; }
  if (!d.to_exists)      { out.push({ json: { ok: false, reason: 'stylist_not_found' } }); continue; }
  if (!d.to_performs)    { out.push({ json: { ok: false, reason: 'stylist_does_not_perform_service' } }); continue; }
  if (!d.to_hours_ok)    { out.push({ json: { ok: false, reason: 'outside_business_hours' } }); continue; }
  if (d.to_busy)         { out.push({ json: { ok: false, reason: 'replacement_busy' } }); continue; }
  if (!d.moved || !d.booking) { out.push({ json: { ok: false, reason: 'not_moved' } }); continue; }
  out.push({ json: { ok: true, data: d.booking } });
}
if (out.length === 0) out.push({ json: { ok: false, reason: 'invalid_input' } });
return out;
